PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS centers (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
INSERT OR IGNORE INTO centers(id,name) VALUES ('edison','Edison'),('princeton','Princeton'),('virginia','Virginia'),('connecticut','Connecticut');
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, center_id TEXT REFERENCES centers(id), first_name TEXT NOT NULL, last_name TEXT NOT NULL, photo_url TEXT, parent_name TEXT, parent_email TEXT, parent_phone TEXT, pole_level INTEGER NOT NULL DEFAULT 1 CHECK(pole_level BETWEEN 1 AND 5), rope_level INTEGER NOT NULL DEFAULT 1 CHECK(rope_level BETWEEN 1 AND 5), yoga_level INTEGER NOT NULL DEFAULT 1 CHECK(yoga_level BETWEEN 1 AND 5), notes TEXT DEFAULT '', active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coaches (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT, phone TEXT, center_id TEXT REFERENCES centers(id), active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS batches (id TEXT PRIMARY KEY, name TEXT NOT NULL, center_id TEXT REFERENCES centers(id), days TEXT DEFAULT '', start_time TEXT DEFAULT '', end_time TEXT DEFAULT '', photo_url TEXT, notes TEXT DEFAULT '', active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS coach_centers (coach_id TEXT NOT NULL REFERENCES coaches(id) ON DELETE CASCADE, center_id TEXT NOT NULL REFERENCES centers(id) ON DELETE CASCADE, PRIMARY KEY(coach_id,center_id));
CREATE TABLE IF NOT EXISTS batch_students (batch_id TEXT REFERENCES batches(id) ON DELETE CASCADE, student_id TEXT REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY(batch_id,student_id));
CREATE TABLE IF NOT EXISTS batch_coaches (batch_id TEXT REFERENCES batches(id) ON DELETE CASCADE, coach_id TEXT REFERENCES coaches(id) ON DELETE CASCADE, PRIMARY KEY(batch_id,coach_id));
CREATE TABLE IF NOT EXISTS student_attendance (id TEXT PRIMARY KEY, batch_id TEXT REFERENCES batches(id), student_id TEXT REFERENCES students(id), attendance_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), UNIQUE(batch_id,student_id,attendance_date));
CREATE TABLE IF NOT EXISTS coach_attendance (id TEXT PRIMARY KEY, batch_id TEXT REFERENCES batches(id), coach_id TEXT REFERENCES coaches(id), attendance_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), UNIQUE(batch_id,coach_id,attendance_date));
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, apparatus TEXT NOT NULL CHECK(apparatus IN ('pole','rope','yoga')), name TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 1 CHECK(level BETWEEN 1 AND 5), description TEXT DEFAULT '', image_url TEXT, video_url TEXT, sort_order INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS student_skill_progress (id TEXT PRIMARY KEY, student_id TEXT REFERENCES students(id) ON DELETE CASCADE, skill_id TEXT REFERENCES skills(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','learning','mastered')), UNIQUE(student_id,skill_id));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, title TEXT NOT NULL, event_type TEXT NOT NULL CHECK(event_type IN ('competition','evaluation','other')), event_date TEXT NOT NULL, center_id TEXT REFERENCES centers(id), details TEXT DEFAULT '', signup_url TEXT, event_time TEXT, location TEXT);
CREATE TABLE IF NOT EXISTS routines (id TEXT PRIMARY KEY, student_id TEXT REFERENCES students(id) ON DELETE CASCADE, apparatus TEXT NOT NULL CHECK(apparatus IN ('pole','rope')), content TEXT DEFAULT '', photo_url TEXT, UNIQUE(student_id,apparatus));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('admin','parent')), student_id TEXT REFERENCES students(id), expires_at INTEGER NOT NULL, parent_id TEXT);
-- Added for parent accounts, links, shop and email. The API also creates these automatically on first request.
CREATE TABLE IF NOT EXISTS links (id TEXT PRIMARY KEY, title TEXT NOT NULL, url TEXT NOT NULL, category TEXT DEFAULT 'Forms', description TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_items (id TEXT PRIMARY KEY, title TEXT NOT NULL, url TEXT NOT NULL, category TEXT DEFAULT 'Gear', price TEXT DEFAULT '', description TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parents (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT DEFAULT '', password_hash TEXT, password_salt TEXT, active INTEGER DEFAULT 1, last_login TEXT, invited_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parent_students (parent_id TEXT NOT NULL REFERENCES parents(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY(parent_id,student_id));
CREATE TABLE IF NOT EXISTS password_tokens (token_hash TEXT PRIMARY KEY, parent_id TEXT NOT NULL REFERENCES parents(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_log (id TEXT PRIMARY KEY, subject TEXT, audience TEXT, total INTEGER DEFAULT 0, sent INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, is_test INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
